upload_auto_resume_hint: "Если загрузка оборвалась посреди передачи — чаще всего из-за краха payload на PS5 — автоматически отправить payload заново и продолжить с места обрыва, сделав несколько попыток, прежде чем сдаться. Фатальные проблемы, например нехватка места на PS5, по-прежнему останавливают загрузку сразу. Включено по умолчанию.",
