reset_hint: "Стереть все локальные следы PS5Upload и начать заново: настройки, сохранённые PS5, историю активности и очереди, кэши payload и отчёты о сбоях. Ничего на вашем PS5 не затрагивается. Сначала экспортируйте резервную копию выше, если она может вам понадобиться.",
reset_action: "Сбросить все настройки и данные",
reset_confirm_title: "Сбросить PS5Upload?",
reset_confirm_body: "Это безвозвратно удалит ВСЕ локальные данные PS5Upload — настройки, сохранённые PS5, историю активности и очереди, кэши payload и отчёты о сбоях. Данные на самом PS5 НЕ затрагиваются. Приложение перезапустится в чистом состоянии. Это нельзя отменить.",
