payloads_add_repo_hint: "Вставьте owner/name (например, EchoStretch/kstuff-lite) или полный URL репозитория. Релизы загружаются так же, как из проверенного списка; при скачивании применяются те же проверки ELF/zip. Добавляйте только те репозитории, которым доверяете — ps5upload не проверяет их содержимое.",
