about_disclaimer_title: "Отказ от ответственности",
about_disclaimer_purpose: "ps5upload предоставляется исключительно для исследовательских, образовательных целей, обеспечения совместимости и разработки homebrew. Он не связан с Sony Interactive Entertainment Inc. и не одобрен ею. «PlayStation» и «PS5» являются товарными знаками Sony Interactive Entertainment Inc. и используются здесь только для идентификации.",
about_disclaimer_piracy: "Используйте его только с оборудованием, которым владеете, и с контентом, которым владеете на законных основаниях. Его нельзя использовать для копирования, распространения или запуска программ, прав на использование которых у вас нет.",
about_disclaimer_risk: "Программа предоставляется «как есть», без каких-либо гарантий. Работа с модифицированной консолью может необратимо повредить её, безвозвратно уничтожить сохранения и лицензии, а также привести к блокировке вашей учётной записи или консоли. Вы используете её полностью на свой страх и риск и принимаете на себя всю ответственность за последствия. Перед началом сделайте резервную копию всего, что не можете позволить себе потерять.",
