upload_split_unsupported_title: "Это разделённый архив ({count} томов), который ps5upload не может открыть",
upload_split_unsupported_body: "При отправке на PS5 попадёт сырой том, который она не сможет использовать. Сначала объедините тома в один архив: откройте первый том в 7-Zip или WinRAR и распакуйте, затем отправьте распакованную папку или один архив с ней.",
