"fpkg.lowSpace": "Мало свободного места: преобразованию может понадобиться до {need} на диске вывода, а там {free}.",
"fpkg.about": "Укажите папку игры или образ монтирования .exfat или .ffpkg. Преобразователь читает дерево, проверяет, что есть всё нужное для запускаемого пакета, и записывает .pkg в отладочном формате в папку вывода.",
"fpkg.aboutWhere": "Преобразование выполняется на машине, где работает движок — на этом компьютере, Docker-хосте или Android-устройстве, — а не на консоли. На консоль ничего не попадает, пока вы не установите пакет — потоком с этого компьютера или сначала загрузив его на PS5.",
"fpkg.aboutSource": "Источник должен быть уже расшифрованным деревом игры. Розничную установку здесь распаковать нельзя, и проверка ниже сообщит, если вы выбрали такую.",
"fpkg.aboutFake": "Результат — фейковый пакет, поэтому перед установкой на консоли должна быть загружена поддержка фейковых пакетов: kstuff (сборка с поддержкой фейковых пакетов PS5), a53_ppr_install_fast.elf и shadowmountplus.elf, в этом порядке. Раздел «Установить пакет» пишет то же рядом со своей кнопкой установки.",
"fpkg.aboutChecks": "Что проверяется",
"fpkg.checkEboot": "Файл eboot.bin в корне дерева — модуль игры. Это должен быть чистый ELF или обёрнутый SELF; модуль с розничной подписью переупаковать нельзя.",
"fpkg.checkParam": "sce_sys/param.json и отсутствие sce_sys/param.sfo — param.sfo направляет запуск на консоли по пути PS4.",
"fpkg.checkIcons": "36-символьный идентификатор контента, обе иконки и модуль прав sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Что значение DRM пакета стандартное. Бесплатное или обновляемое значение заставляет консоль заблокировать игру; оно переписывается только в пакете, ваш собственный файл не изменяется.",
"payloads_essentials_title": "Рекомендуется вместе с ps5upload",
"payloads_essentials_body": "Если вы настраиваете консоль впервые, эти три покрывают почти всё, что ожидает ps5upload: kstuff-lite (патчи ядра, на которые опирается большинство homebrew), ShadowMount+ (монтирование образов игр из хранилища) и nanoDNS (держит консоль подальше от обновлений Sony). Всё остальное в этом списке необязательно.",
"payloads_tab_shadowmount": "ShadowMount+",
"payloads_tab_nanodns": "nanoDNS",
