"bug_report_open_github": "Открыть issues на GitHub",
"bug_report_post_hint_v2": "Теперь отправьте его туда, где его увидят: создайте issue на GitHub и приложите .zip или опубликуйте его в канале Discord для отчётов об ошибках. GitHub лучше для всего, что нужно отслеживать до исправления; Discord быстрее, если вы хотите просто спросить, известна ли проблема. В любом случае кратко опишите, что вы делали.",
