"profile.accountId.confirm_set": "Установить ID учётной записи слота {slot} на {next}?\n\nЭто активирует автономную учётную запись. Сохранения, сделанные с этого момента, привязаны к этому ID — если позже изменить его, они перестанут распознаваться, пока вы не вернёте прежний.",
"pkglib.url.title": "Установка по ссылке HTTP(S)",
"pkglib.url.help": "Этот компьютер скачивает пакет сразу по нескольким соединениям и передаёт его PS5 по вашей сети, поэтому передача идёт со скоростью вашего канала, а не медленного одиночного потока консоли. Ничего не сохраняется ни на одной из машин, так что игре на 100 ГБ не нужно свободное место. Ссылка должна вести на прямую загрузку с поддержкой диапазонов байтов. Не давайте этому компьютеру уснуть до конца установки.",
"pkglib.url.label": "Прямая ссылка на пакет",
"pkglib.url.install": "Установить по ссылке",
"pkglib.url.confirmTitle": "Начать экспериментальную установку по ссылке?",
"pkglib.url.confirmBody": "Этот компьютер скачивает пакет по ссылке и передаёт его PS5, поэтому он должен оставаться включённым и подключённым до конца установки. Переустановка поверх существующей игры может удалить её, если установщик Sony даст сбой. Используйте только надёжную ссылку на пакет, который вам разрешено устанавливать.",
"pkglib.url.confirm": "Начать установку",
"pkglib.url.failed": "Установка по ссылке не завершилась.",
