"fs_replace_tooltip": "Перезаписать этот файл файлом с вашего компьютера — так исправляют файл внутри смонтированного образа игры",
"fs_replace_dialog_title": "Выберите файл для замены «{name}»",
"fs_replace_confirm_title": "Заменить этот файл?",
"fs_replace_confirm_body": "«{name}» будет перезаписан, а прежнее содержимое пропадёт навсегда. Если он внутри смонтированного образа игры, неправильный файл может помешать запуску игры.",
"fs_replace_confirm_ok": "Заменить",
"fs_busy_uploading": "Копирование на PS5",
"notif_fs_upload_failed": "Не удалось скопировать на PS5",
"volumes_mounted_rw": "чтение и запись",
"pkg.patch_loader_not_listening": "Не удалось применить это обновление: загрузчик payload на вашей PS5 работает, но не принимает подключения на порту 9021, поэтому нужный установщик так и не был доставлен и консоль не увидела обновление. Базовая игра не затронута. Загрузите его снова со своей страницы джейлбрейка — процесс загрузчика, уже отдавший один payload, не всегда продолжает слушать. Обновление уже на вашей PS5, поэтому ничего не нужно загружать заново — повторите установку из списка пакетов. Можно также применить обновление на самой PS5: Настройки → Система → Настройки отладки → Игра → Package Installer.",
"pkg.reverify_impossible": "PS5 приняла эту установку, но у ps5upload нет данных, по которым можно опознать установленный пакет, поэтому подтвердить её нельзя. Результат смотрите в уведомлениях PS5. Подготовленный пакет сохранён.",
"pkg.reverify_gave_up": "Всё ещё не подтверждено через 30 минут. Очень большая игра может устанавливаться дольше — проверьте уведомления PS5 или нажмите «Проверить снова».",
"backport_action": "Бэкпорт",
"backport_auto": "Перебирать наборы автоматически",
"backport_auto_hint": "Устанавливает набор, запускает игру и, если она не стартует, отменяет изменения и переходит к следующему — пока один не заработает или наборы не кончатся.",
"backport_auto_running": "Пробуем {label} — набор {index} из {total}…",
