"backport_title": "Бэкпорт {name}",
"backport_overlay_unavailable": "Наложение библиотек недоступно",
"backport_overlay_external": "Уже активно внешнее наложение BackPork/unionfs.",
"backport_overlay_missing": "Перед бэкпортом отправьте текущий payload ps5upload. Старые payload не могут смонтировать выбранные библиотеки при запуске игры.",
"backport_failed": "Не удалось завершить бэкпорт",
"backport_inspecting": "Проверка установленных семейств библиотек…",
"backport_summary": "Игра будет понижена до пары SDK FW 4, и будет установлен набор из {count} библиотек, поставляемый с {set}. Набор устанавливается целиком — смешивание библиотек из разных игр и приводит к тому, что бэкпорт не запускается.",
"settings_card_fakelibs": "Библиотеки для бэкпорта",
"backport_verify_unpatched": "Для этой игры не сделан бэкпорт",
"backport_verify_unpatched_body": "Её eboot всё ещё содержит исходную версию SDK, поэтому она не может работать на этой прошивке, какие бы библиотеки ни были установлены — дело не в наборе библиотек. Выполните бэкпорт снова; если повторится, патч SDK не применяется.",
"backport_no_larger": "Этой игре нужны библиотеки, которых нет ни в одном вашем наборе. Импортируйте более полный пакет или просканируйте другую консоль.",
"backport_verifying": "Запуск и наблюдение — неудачный запуск повторяется, потому что запуск настолько ненадёжен, что одна неудача ничего не доказывает.",
"backport_verify_running": "Игра работает — доходит ли до геймплея?",
"backport_verify_running_body": "Игра всё ещё работает спустя минуту (потоков: {threads}). Значит, она не упала при загрузке, но это не значит, что в неё можно играть — посмотрите на экран. Оставьте, если работает, или отмените и попробуйте следующий набор.",
"backport_verify_missing": "Нужно больше библиотек",
"backport_verify_missing_body": "Игра вызвала функцию, которой нет ни в одной установленной библиотеке. Осталось более крупных наборов: {count}.",
"backport_verify_wrong": "Не те библиотеки для этой игры",
"backport_verify_wrong_body": "Игра пропатчена правильно, но не запустилась с этими библиотеками, значит, ей нужны другие. Осталось других наборов: {count}.",
"backport_verify_unknown": "Не удалось понять, сработало ли",
"backport_verify_unknown_body": "Запуски дали разные результаты, так что о библиотеках это ничего не говорит — запуск сам по себе срывается так часто, что смешанный результат ничего не значит. Попробуйте запустить игру сами и отмените, если играть нельзя.",
