"joberr.ava1_refused": "PS5 отклонила этот запрос (код {code}). Повторите; если повторяется, обновите помощник и приложение до одной версии и приложите код к отчёту об ошибке.",
"joberr.ava1_busy": "Помощник PS5 занят и не принял эту передачу вовремя. Дождитесь окончания его другой работы и нажмите «Повторить».",
"joberr.ava1_unreachable": "PS5 недоступна. Убедитесь, что она включена, в той же сети и помощник запущен, затем нажмите «Повторить».",
"joberr.ava1_exists": "Место назначения уже существует на PS5. Выберите «Перезаписать», чтобы заменить его, или другое место.",
"joberr.ava1_commit_exists": "Файл загружен, но не опубликован, потому что место назначения уже существует. Выберите «Перезаписать», чтобы заменить его, или другое место.",
"joberr.ava1_cross_device": "Место назначения находится на другом диске, чем область подготовки, поэтому PS5 не смогла переместить файл. Выберите место на том же диске или сначала загрузите на внутренний диск.",
"joberr.ava1_wrong_console": "Устройство по этому адресу — не та PS5, с которой сопряжено приложение. Проверьте адрес или сопрягите эту консоль заново.",
"joberr.ava1_no_identity": "У приложения пока нет идентификатора сопряжения. Сопрягите его с PS5 на экране «Подключение» и повторите.",
"joberr.zip_read_error": "Не удалось прочитать .zip (файл или его диск мог пропасть во время чтения). Проверьте, что источник всё ещё подключён, и нажмите «Повторить».",
"joberr.ava1_zip_corrupt": "Не удалось прочитать этот .zip: он повреждён или неполон. Скачайте или создайте его заново и повторите.",
"joberr.ava1_7z_corrupt": "Не удалось прочитать этот .7z: он повреждён или неполон. Скачайте или создайте его заново и повторите.",
"joberr.ava1_7z_encrypted": "Этот .7z зашифрован и не может быть передан потоком. Распакуйте его на компьютере и загрузите папку.",
"joberr.ava1_7z_unsafe_path": "Этот .7z содержит небезопасный путь к файлу (выходит за пределы своей папки). Распакуйте его на компьютере и загрузите папку.",
"joberr.rar_password": "Для этого .rar нужен пароль, либо введённый пароль неверен. Введите правильный пароль и повторите.",
"joberr.rar_corrupt": "Этот .rar повреждён, либо некоторые его части отсутствуют или идут в неверном порядке. Убедитесь, что все части на месте, и повторите.",
"joberr.ava1_copy_lost": "PS5 потеряла это копирование (помощник перезапустился или соединение оборвалось). Нажмите «Повторить», чтобы начать заново.",
"joberr.ava1_copy_failed": "PS5 не смогла завершить копирование. Проверьте свободное место и доступность источника и места назначения, затем повторите.",
"joberr.ava1_local_io": "Этот компьютер не смог записать скачанный файл. Проверьте права и свободное место в папке назначения и повторите.",
"joberr.ava1_bad_manifest": "PS5 прислала список файлов, который приложение не поняло. Обновите помощник и приложение до одной версии и повторите.",
"joberr.helper_not_ava1": "Помощник PS5 не запущен. Отправьте его с экрана «Подключение» (или используйте «Обновить помощник», если баннер это предлагает) и повторите.",
"joberr.helper_not_ava1_web": "Помощник PS5 не запущен. Этот веб-интерфейс не может его отправить: запустите payload ps5upload на консоли своим обычным загрузчиком payload (или используйте «Обновить помощник», если баннер это предлагает) и повторите.",
"joberr.helper_old": "На PS5 работает более старый помощник. Нажмите «Обновить помощник» в баннере сверху и повторите.",
