volumes_pkg_copies_hint: "Что делает этот выбор: «Загрузить и установить» сначала копирует файл .pkg на PS5, а затем устанавливает из этой копии. Здесь задаётся только диск, на котором лежат эти копии. Место установки игр не меняется (его определяет PS5 в своих настройках хранилища), а «Стримить и установить» вообще не оставляет копий. Если выбранный диск не подключён, копии попадают во внутреннюю память.",
