captures: "Скриншоты и клипы",
captures_title: "Записи",
"arcpkg.choose": "Выбрать архив…",
"arcpkg.help": "Для .zip, .7z или .rar, в котором лежит один или несколько файлов .pkg в любых папках. Распаковываются только пакеты, сразу на PS5 (на этом компьютере ничего не извлекается), затем они устанавливаются по одному: сначала базовая игра, потом её обновление, потом DLC. Многотомный RAR (.part1.rar, .part2.rar…) поддерживается: выберите первую часть, а остальные держите рядом. Пароль запрашивается, когда он нужен для RAR; ZIP и 7z с паролем не поддерживаются.",
"arcpkg.keepsRunning": "Это продолжит работать, если открыть другой экран; оно также видно в «Задачах».",
"arcpkg.notArchive": "Этот файл не является архивом .zip, .7z или .rar.",
"arcpkg.pick": "Выберите архив",
