"install.library.title": "Копии пакетов на PS5",
"install.stream.file.help": "Выберите .pkg или .fpkg либо перетащите его в любое место этого окна. Не закрывайте приложение до конца установки; ход виден в очереди выше и в «Задачах».",
"install.stream.file.title": "Установить файл пакета",
"install.tab.stream.lead": "PS5 устанавливает прямо с этого компьютера или по ссылке. Копия на PS5 заранее не кладётся, поэтому свободное место там не нужно, и это самый надёжный способ установки.",
"install.tab.upload.lead": "Пакет сначала копируется на PS5, а затем устанавливается из этой копии. Используйте, когда PS5 не может достучаться до этого компьютера (стриминг завершается сетевой ошибкой) или чтобы хранить пакеты на PS5 и переустанавливать их позже без этого компьютера.",
"install.upload.file.browser": "Чтобы скопировать пакет на PS5 отсюда, нужно настольное приложение. В веб-интерфейсе используйте «Стриминг и установка» или установите ниже пакеты, которые уже лежат на PS5.",
"install.upload.file.help": "Выберите .pkg или .fpkg. Копии нужно свободное место на PS5 под весь пакет, и она остаётся в списке ниже, пока вы её не удалите.",
"install.upload.file.title": "Скопировать пакет на PS5 и установить его",
"linkcard.confirm.direct": "PS5 сама скачивает пакет по ссылке и устанавливает его. После запуска этот компьютер больше не нужен, а ход виден на PS5 (Загрузки), а не здесь. Если PS5 не сможет получить ссылку, приложение передаст её через этот компьютер. Переустановка поверх установленной игры может удалить её, если установщик Sony даст сбой. Используйте только ссылки на пакеты, которым доверяете и которые вправе устанавливать.",
"linkcard.confirm.download": "Этот компьютер сначала сохраняет весь пакет на диск, а затем устанавливает его на PS5. Он должен оставаться включённым до конца обоих этапов, и на нём нужно свободное место под пакет. Переустановка поверх установленной игры может удалить её, если установщик Sony даст сбой. Используйте только ссылки на пакеты, которым доверяете и которые вправе устанавливать.",
"linkcard.confirm.stream": "Этот компьютер скачивает пакет и сразу передаёт его на PS5, поэтому он должен оставаться включённым и на связи до конца установки. На диск ничего не сохраняется. Переустановка поверх установленной игры может удалить её, если установщик Sony даст сбой. Используйте только ссылки на пакеты, которым доверяете и которые вправе устанавливать.",
"linkcard.confirm.title": "Установить по этой ссылке?",
"linkcard.fact.awake": "Не давайте компьютеру уснуть",
"linkcard.fact.can_close": "Приложение можно закрыть",
"linkcard.fact.disk": "Нужно место на диске здесь",
"linkcard.fact.no_disk": "Место на диске не нужно",
"linkcard.fact.progress_here": "Ход виден здесь",
"linkcard.fact.progress_ps5": "Ход виден на PS5",
"linkcard.forget": "Убрать из списка",
"linkcard.help": "Вставьте прямую ссылку на .pkg. На PS5 заранее ничего не копируется, так что игре на 100 ГБ не нужно там лишнее место.",
"linkcard.how": "Как его получить?",
"linkcard.insecure": "Пропустить проверку сертификата",
"linkcard.insecure_hint": "Для своего сервера или сайта с просроченным сертификатом. Действует здесь, потому что соединение устанавливает этот компьютер.",
"linkcard.install": "Установить по ссылке",
"linkcard.mode.direct": "PS5 скачивает сама",
"linkcard.mode.direct_body": "PS5 сама получает ссылку. Она должна иметь доступ к ссылке, а адрес должен быть коротким (длинный приложение сокращает и тогда должно оставаться открытым).",
"linkcard.mode.download": "Сначала скачать сюда, потом установить",
"linkcard.mode.download_body": "Этот компьютер сохраняет весь пакет, затем устанавливает его. Самый медленный способ, но если ссылка истечёт или оборвётся, придётся лишь повторить загрузку.",
"linkcard.mode.stream": "Стриминг через этот компьютер",
"linkcard.mode.stream_body": "Этот компьютер скачивает в несколько соединений и сразу передаёт на PS5. Обычно это быстрее всего и работает, когда ссылка доступна только этому компьютеру.",
"linkcard.name": "Название (необязательно)",
"linkcard.name_hint": "Название показывается в очереди, в «Задачах» и в недавних ссылках вместо адреса, чтобы различать ссылки и повторять нужную.",
"linkcard.name_placeholder": "напр. Astro Bot обновление 1.05",
"linkcard.recent": "Недавние ссылки",
"linkcard.recommended": "Рекомендуется",
"linkcard.rename": "Переименовать",
"linkcard.title": "Установить по ссылке",
"linkcard.url": "Ссылка",
"linkcard.use": "Использовать",
"install.description.v2": "Устанавливайте пакеты .pkg и .fpkg на PS5: прямо с этого компьютера или по ссылке («Стриминг и установка») либо из копии, сначала помещённой на PS5 («Загрузить и установить»).",
faq_collapse_all: "Закрыть все",
