faq_description_v2: "Как настроить, передавать, устанавливать и исправлять. Ищите слово или код ошибки либо выберите раздел.",
faq_expand_all: "Открыть все",
faq_results: "Ответов: {count}",
faq_section: "Раздел",
faq_topics: "Темы",
health_junk_explain_v2: "То, что создал ps5upload и что больше не нужно: незавершённые файлы прерванных передач, копии пакетов, пролежавшие во временной папке больше часа, и старые файлы теста скорости. Просматриваются только собственные папки ps5upload; ваши игры, пакеты и сохранения не затрагиваются никогда.",
home_health_checking: "Проверяем, что всё работает…",
home_health_desc: "Порты, соединение, хранилище и настройка, проверенные для этой консоли.",
