"collection.trash_unavailable_v2": "У этого движка нет корзины. Чтобы удалять копии отсюда, включите «Разрешить безвозвратное удаление копий» в разделе Коллекция → Папки.",
"pkg.sony_80b21104": "PS5 не приняла этот пакет (0x80B21104). Если другие пакеты на эту консоль ставятся, дело в этом файле: чаще всего это новая игра, пакет которой собран инструментами новее, чем понимает прошивка этой консоли, или пакет, который не является сборкой с поддельной подписью (FPKG). Возьмите пакет для вашей прошивки (бэкпорт) или установите игру в обход установщика: скопируйте её папку игры или образ игры (.exfat или .ffpfsc) для ShadowMount+ через «Загрузить».",
